package stepup

import (
	"os"
	"slices"
	"testing"

	"github.com/Jlore-Studios/JackiOh/bot/go/internal/pyjson"
)

// setorder.json is `list({target, *([pr] if pr else [])})` as CPython gives it, for each pair
// (generated by running it).
func TestThreadsOfIsCPythonsSetOrder(t *testing.T) {
	raw, err := os.ReadFile("testdata/setorder.json")
	if err != nil {
		t.Fatal(err)
	}
	data, err := pyjson.Loads(raw)
	if err != nil {
		t.Fatal(err)
	}
	for _, row := range data.([]any) {
		r := row.([]any)
		target, _ := pyjson.AsInt(r[0])
		var pr *int
		if n, ok := pyjson.AsInt(r[1]); ok {
			pr = &n
		}
		var want []int
		for _, n := range r[2].([]any) {
			v, _ := pyjson.AsInt(n)
			want = append(want, v)
		}
		if got := threadsOf(target, pr); !slices.Equal(got, want) {
			t.Errorf("threadsOf(%d, %v) = %v, want %v", target, r[1], got, want)
		}
	}
}

func TestReasonsText(t *testing.T) {
	if got := reasonsText([]string{"a", "", "b", "a"}); got != "a; b" {
		t.Errorf("reasonsText = %q", got)
	}
	if got := reasonsText([]string{"", ""}); got != "no reason recorded" {
		t.Errorf("reasonsText of nothing = %q", got)
	}
	if got := lastN([]any{1, 2, 3}, 2); pyjson.Dumps(got) != "[2, 3]" {
		t.Errorf("lastN = %s", pyjson.Dumps(got))
	}
}
